/* Version nodes of the yolo glibc's libc (libyolocimpl.so), so that Fil-C objects'
   version requirements on it are satisfied: every version name that the
   distribution's libraries list for it in their VERNEED entries. */

GLIBC_2.2.5 {
  global:
    libc_internal_signals;
    num_libc_internal_signals;
    sigdelsetyolo;
    yolo_futex_wake;
    yolo_futex_wait;
    yolo_futex_timedwait;
    yolo_futex_unlock_pi;
    yolo_futex_lock_pi;
    yolo_futex_requeue;
    fil_rust_sigaction;
    fil_rust_signals_init;
  local: *;
};
GLIBC_2.3 { };
